// Lasthome (Chapter 3): the living town built in the biggest hall of the
// half-sunk old city, where the people who stopped waiting for the Hero went,
// generations ago. Marmots (like the heralds of Heralds' Rest) and people
// (like Bramble), warm, lamplit, tired and kind. These are its houses (each
// one its own, drawn whole, smoke going up: see HOUSE_PALETTE), its
// townsfolk, its market, its forge yard and its odds and ends, drawn like
// the props in props.js (rows of characters, standing on their tile's bottom
// edge, centred), in PROP_PALETTE's colours only: no new colours needed. The
// big ones' widths in tiles are in LASTHOME_FOOTPRINTS.
//
// Also here: the faces of Bryony and Thistle, for the dialogue box (added to
// PORTRAITS in portraits.js as 'bryony' and 'thistle').

// --- The houses of the square ---
// Each is one big prop, drawn whole: its own roof, chimney, door, windows
// and clutter, so no two look alike. They're animated (four frames each, at
// `speed` 0.4 or so): smoke drifts off the chimneys, and the forge's fire
// flickers. A room stands one on its tiles by its first frame (house_inn in
// LASTHOME_PROP_SPRITES, below) and plays the rest with `animation:
// 'house_inn'`. The tiles under them do the blocking (the room's cottage
// walls), so they're `walkable`. 96 rows tall: the top 16 are headroom for
// the smoke, the house itself fills the 80 under.
// Their colours are PROP_PALETTE's, for the same letters: this copy is the
// palette the animation frames are played with.
